 renderedCallback(){trace.push('root:rendered');}
 disconnectedCallback(){trace.push('root:disconnected');}
 errorCallback(error,stack){trace.push({callback:'root:errorCallback',name:error.name,message:error.message,stackPresent:typeof stack==='string'&&stack.length>0});}
 get output(){trace.push('root:getter');return this.value;}
 @api advance(index){return ACTIONS[index].call(this);}
